            if (ExpectKeyword("None"))
            {
                // 'None' { _PyAST_Constant(Py_None, NULL, EXTRA) }
                var noneExpr = new GeneratedExpr();
                // TODO: Set None constant properties when structure is defined
                return noneExpr;
            }

            // TODO: Add other atom alternatives
